    static func tabIcon(_ index: Int) -> UIImage? {
        switch index {
        case 0: return imageAlbum
        case 1: return imageMonths
        case 2: return imageContactsCircle
        default: return nil
        }
    }

    private static func render(viewport: CGFloat, commands: String) -> UIImage {
        UIGraphicsImageRenderer(size: CGSize(width: 24, height: 24)).image { renderer in
            let context = renderer.cgContext
            context.scaleBy(x: 24 / viewport, y: 24 / viewport)
            context.translateBy(x: 0, y: viewport)
            context.scaleBy(x: 1, y: -1)
            context.setFillColor(UIColor.black.cgColor)
            context.beginPath()
            for command in commands.split(whereSeparator: { $0.isWhitespace }) {
                if command == "Z" {
                    context.closePath()
                    continue
                }
                let values = command.dropFirst().split(separator: ",").map { CGFloat(Double($0)!) }
                let point = CGPoint(x: values[0], y: values[1])
                switch command.first {
                case "M": context.move(to: point)
                case "L": context.addLine(to: point)
                case "Q":
                    context.addQuadCurve(to: point, control: CGPoint(x: values[2], y: values[3]))
                default: preconditionFailure("Unsupported generated vector command")
                }
            }
            context.fillPath()
        }
    }
